@component()
export class ButtonTapDebug extends APJS.BasicScriptComponent {
  @serializeProperty
  attackButton!: APJS.SceneObject;

  @serializeProperty
  defenseButton!: APJS.SceneObject;

  private attackImage!: APJS.Image;
  private defenseImage!: APJS.Image;
  private initialized = false;

  private touchCallback = (event: APJS.IEvent) => {
    if (!this.initialized) return;

    const touchInfo = event.args[0] as APJS.TouchData;
    if (touchInfo.phase !== APJS.TouchPhase.Began) return;

    if (APJS.TouchUtils.isScreenPointOnImage(touchInfo.position, this.attackImage)) {
      console.log("[Button Debug] ATTACK tapped");
    } else if (APJS.TouchUtils.isScreenPointOnImage(touchInfo.position, this.defenseImage)) {
      console.log("[Button Debug] DEFENSE tapped");
    }
  };

  onUpdate(_dt: number): void {
    if (this.initialized || !this.attackButton || !this.defenseButton) return;

    const attack = this.attackButton.getComponent("Image");
    const defense = this.defenseButton.getComponent("Image");
    if (!attack || !defense) return;

    this.attackImage = attack as APJS.Image;
    this.defenseImage = defense as APJS.Image;
    APJS.EventManager.getGlobalEmitter().on(APJS.EventType.Touch, this.touchCallback, this);
    this.initialized = true;
    console.log("[Button Debug] Ready");
  }

  onDestroy(): void {
    if (this.initialized) {
      APJS.EventManager.getGlobalEmitter().off(APJS.EventType.Touch, this.touchCallback, this);
    }
  }
}

@component()
export class BattleManager extends APJS.BasicScriptComponent {
  @header("Theme & Assets")
  @serializeProperty
  @tooltip("Mage idle animation used when neither fighter is attacking.")
  idleTex!: APJS.Texture;

  @serializeProperty
  @tooltip("Mage attack animation used at the start of each shot.")
  attackTex!: APJS.Texture;

  @serializeProperty
  @tooltip("One-shot death animation for the fighter whose HP reaches zero.")
  deadTex!: APJS.Texture;

  @serializeProperty
  @tooltip("Animated WaterBall that grows and flies toward the target.")
  projectileTex!: APJS.Texture;

  @serializeProperty
  @tooltip("One-shot WaterBall splash shown when a hit lands.")
  impactTex!: APJS.Texture;

  @header("Gameplay Tuning")
  @serializeProperty
  @tooltip("Starting health for both fighters.")
  @spinBox(1, 500, 1)
  maxHp: number = 100;

  @serializeProperty
  @tooltip("Minimum normal damage dealt by one hit.")
  @spinBox(1, 50, 1)
  minDamage: number = 10;

  @serializeProperty
  @tooltip("Maximum normal damage dealt by one hit.")
  @spinBox(1, 50, 1)
  maxDamage: number = 15;

  @serializeProperty
  @tooltip("Chance for an attack to deal critical damage.")
  @slider(0, 0.5, 0.01)
  critRate: number = 0.15;

  @serializeProperty
  @tooltip("Critical damage multiplier.")
  @slider(1, 3, 0.1)
  critMultiplier: number = 2;

  @serializeProperty
  @tooltip("Preparation countdown duration before each exchange.")
  @spinBox(1, 30, 1)
  prepareSec: number = 10;

  @serializeProperty
  @tooltip("How long the WaterBall takes to fly to the other fighter.")
  @slider(0.1, 2, 0.1)
  flightSec: number = 0.5;

  @serializeProperty
  @tooltip("How long the impact splash remains visible.")
  @slider(0.2, 2, 0.1)
  impactSec: number = 1;

  @header("Advanced — Scene Wiring")
  @serializeProperty
  @tooltip("Player A character object.")
  playerObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Bot B character object.")
  botObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Player A health fill image object.")
  playerHealthObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Bot B health fill image object.")
  botHealthObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Turn number label.")
  turnObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Countdown and winner callout label.")
  countdownObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("WaterBall projectile scene object.")
  projectileObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("WaterBall impact scene object.")
  impactObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Retry button shown after the winner callout.")
  retryObj!: APJS.SceneObject;

  private readonly ATTACK_WINDUP_SEC: number = 0.5;
  private readonly PROJECTILE_GROW_SEC: number = 0.5;
  private readonly CAST_HOLD_SEC: number = 0.5;
  private readonly FIGHT_BANNER_SEC: number = 1;
  private readonly DEAD_ANIMATION_SEC: number = 1.17;

  private ready: boolean = false;
  private eventsBound: boolean = false;
  private phase: string = "waiting";
  private timer: number = 0;
  private turn: number = 1;
  private countdownValue: number = 10;
  private playerHp: number = 100;
  private botHp: number = 100;
  private attackerIsPlayer: boolean = true;
  private resultText: string = "";
  private impactVisible: boolean = false;

  private playerImage!: APJS.Image;
  private botImage!: APJS.Image;
  private playerTransform!: APJS.ScreenTransform;
  private botTransform!: APJS.ScreenTransform;
  private playerHealthImage!: APJS.Image;
  private botHealthImage!: APJS.Image;
  private turnLabel!: APJS.Text;
  private countdownLabel!: APJS.Text;
  private projectileImage!: APJS.Image;
  private projectileTransform!: APJS.ScreenTransform;
  private impactImage!: APJS.Image;
  private impactTransform!: APJS.ScreenTransform;
  private retryImage!: APJS.Image;
  private attackerImage!: APJS.Image;
  private victimImage!: APJS.Image;
  private attackerStart!: APJS.Vector2f;
  private victimEnd!: APJS.Vector2f;

  private onTouch = (event: APJS.IEvent): void => {
    const touch = event.args[0] as APJS.TouchData;
    if (this.phase !== "result" || touch.phase !== APJS.TouchPhase.Began) {
      return;
    }
    if (APJS.TouchUtils.isScreenPointOnImage(touch.position, this.retryImage)) {
      this.resetBattle();
    }
  };

  private onRecordStart = (_event: APJS.IEvent): void => {
    if (this.ready) {
      this.resetBattle();
    }
  };

  onUpdate(dt: number): void {
    if (!this.ready) {
      this.initialize();
      return;
    }

    const delta = Math.max(0, dt);
    switch (this.phase) {
      case "prepare":
        this.tickPreparation(delta);
        break;
      case "fight":
        this.timer += delta;
        if (this.timer >= this.FIGHT_BANNER_SEC) {
          this.countdownObj.setEnabledInHierarchy(false);
          this.beginAttack(true);
        }
        break;
      case "windup":
        this.timer += delta;
        if (this.timer >= this.ATTACK_WINDUP_SEC) {
          this.spawnProjectile();
        }
        break;
      case "grow":
        this.tickProjectileGrowth(delta);
        break;
      case "castHold":
        this.timer += delta;
        if (this.timer >= this.CAST_HOLD_SEC) {
          this.phase = "fly";
          this.timer = 0;
        }
        break;
      case "fly":
        this.tickProjectileFlight(delta);
        break;
      case "impact":
        this.timer += delta;
        if (this.timer >= this.impactSec) {
          this.finishImpact();
        }
        break;
      case "death":
        this.tickDeath(delta);
        break;
    }
  }

  onDestroy(): void {
    if (!this.eventsBound) {
      return;
    }
    const emitter = APJS.EventManager.getGlobalEmitter();
    emitter.off(APJS.EventType.Touch, this.onTouch, this);
    emitter.off(APJS.EventType.RecordStart, this.onRecordStart, this);
  }

  private initialize(): void {
    if (
      !this.idleTex || !this.attackTex || !this.deadTex ||
      !this.projectileTex || !this.impactTex || !this.playerObj ||
      !this.botObj || !this.playerHealthObj || !this.botHealthObj ||
      !this.turnObj || !this.countdownObj || !this.projectileObj ||
      !this.impactObj || !this.retryObj
    ) {
      return;
    }

    this.playerImage = this.playerObj.getComponent("Image") as APJS.Image;
    this.botImage = this.botObj.getComponent("Image") as APJS.Image;
    this.playerTransform = this.playerObj.getComponent("ScreenTransform") as APJS.ScreenTransform;
    this.botTransform = this.botObj.getComponent("ScreenTransform") as APJS.ScreenTransform;
    this.playerHealthImage = this.playerHealthObj.getComponent("Image") as APJS.Image;
    this.botHealthImage = this.botHealthObj.getComponent("Image") as APJS.Image;
    this.turnLabel = this.turnObj.getComponent("Text") as APJS.Text;
    this.countdownLabel = this.countdownObj.getComponent("Text") as APJS.Text;
    this.projectileImage = this.projectileObj.getComponent("Image") as APJS.Image;
    this.projectileTransform = this.projectileObj.getComponent("ScreenTransform") as APJS.ScreenTransform;
    this.impactImage = this.impactObj.getComponent("Image") as APJS.Image;
    this.impactTransform = this.impactObj.getComponent("ScreenTransform") as APJS.ScreenTransform;
    this.retryImage = this.retryObj.getComponent("Image") as APJS.Image;

    if (
      !this.playerImage || !this.botImage || !this.playerTransform ||
      !this.botTransform || !this.playerHealthImage || !this.botHealthImage ||
      !this.turnLabel || !this.countdownLabel || !this.projectileImage ||
      !this.projectileTransform || !this.impactImage || !this.impactTransform ||
      !this.retryImage
    ) {
      return;
    }

    this.maxHp = this.clampInt(this.maxHp, 1, 500);
    this.minDamage = this.clampInt(this.minDamage, 1, 50);
    this.maxDamage = Math.max(this.minDamage, this.clampInt(this.maxDamage, 1, 50));
    this.critRate = this.clamp(this.critRate, 0, 0.5);
    this.critMultiplier = this.clamp(this.critMultiplier, 1, 3);
    this.prepareSec = this.clampInt(this.prepareSec, 1, 30);
    this.flightSec = this.clamp(this.flightSec, 0.1, 2);
    this.impactSec = this.clamp(this.impactSec, 0.2, 2);

    this.ready = true;
    const emitter = APJS.EventManager.getGlobalEmitter();
    emitter.on(APJS.EventType.Touch, this.onTouch, this);
    emitter.on(APJS.EventType.RecordStart, this.onRecordStart, this);
    this.eventsBound = true;
    this.resetBattle();
  }

  private resetBattle(): void {
    this.playerHp = this.maxHp;
    this.botHp = this.maxHp;
    this.turn = 1;
    this.resultText = "";
    this.impactVisible = false;
    this.timer = 0;
    this.turnLabel.text = "Turn 1";
    this.updateHealthBars();
    this.playGif(this.playerImage, this.idleTex);
    this.playGif(this.botImage, this.idleTex);
    this.projectileObj.setEnabledInHierarchy(false);
    this.impactObj.setEnabledInHierarchy(false);
    this.retryObj.setEnabledInHierarchy(false);
    this.projectileTransform.scale = new APJS.Vector2f(1, 1);
    this.countdownObj.setEnabledInHierarchy(true);
    this.startPreparation();
  }

  private startPreparation(): void {
    this.phase = "prepare";
    this.timer = 0;
    this.countdownValue = this.prepareSec;
    this.turnLabel.text = "Turn " + this.turn;
    this.countdownLabel.text = String(this.countdownValue);
    this.countdownObj.setEnabledInHierarchy(true);
  }

  private tickPreparation(dt: number): void {
    this.timer += dt;
    if (this.timer < 1) {
      return;
    }
    this.timer -= 1;
    if (this.countdownValue > 1) {
      this.countdownValue -= 1;
      this.countdownLabel.text = String(this.countdownValue);
      return;
    }
    this.countdownLabel.text = "Fight";
    this.phase = "fight";
    this.timer = 0;
  }

  private beginAttack(playerAttacks: boolean): void {
    this.attackerIsPlayer = playerAttacks;
    this.attackerImage = playerAttacks ? this.playerImage : this.botImage;
    this.victimImage = playerAttacks ? this.botImage : this.playerImage;
    const attackerTransform = playerAttacks ? this.playerTransform : this.botTransform;
    const victimTransform = playerAttacks ? this.botTransform : this.playerTransform;
    this.attackerStart = this.screenCenter(attackerTransform);
    this.victimEnd = this.screenCenter(victimTransform);
    this.playGif(this.attackerImage, this.attackTex);
    this.projectileObj.setEnabledInHierarchy(false);
    this.phase = "windup";
    this.timer = 0;
  }

  private spawnProjectile(): void {
    this.projectileTransform.anchoredPosition = new APJS.Vector2f(
      this.attackerStart.x,
      this.attackerStart.y,
    );
    this.projectileTransform.scale = new APJS.Vector2f(0, 0);
    this.projectileObj.setEnabledInHierarchy(true);
    this.playGif(this.projectileImage, this.projectileTex);
    this.phase = "grow";
    this.timer = 0;
  }

  private tickProjectileGrowth(dt: number): void {
    this.timer += dt;
    const amount = this.clamp(this.timer / this.PROJECTILE_GROW_SEC, 0, 1);
    this.projectileTransform.scale = new APJS.Vector2f(amount, amount);
    if (amount >= 1) {
      this.phase = "castHold";
      this.timer = 0;
    }
  }

  private tickProjectileFlight(dt: number): void {
    this.timer += dt;
    const amount = this.clamp(this.timer / this.flightSec, 0, 1);
    const x = this.attackerStart.x + (this.victimEnd.x - this.attackerStart.x) * amount;
    const y = this.attackerStart.y + (this.victimEnd.y - this.attackerStart.y) * amount;
    this.projectileTransform.anchoredPosition = new APJS.Vector2f(x, y);
    if (amount >= 1) {
      this.applyHit();
    }
  }

  private applyHit(): void {
    this.projectileObj.setEnabledInHierarchy(false);
    this.impactTransform.anchoredPosition = new APJS.Vector2f(
      this.victimEnd.x,
      this.victimEnd.y,
    );
    this.impactTransform.scale = new APJS.Vector2f(1, 1);
    this.impactObj.setEnabledInHierarchy(true);
    this.playGif(this.impactImage, this.impactTex);
    this.playGif(this.attackerImage, this.idleTex);

    const base = this.randomInt(this.minDamage, this.maxDamage);
    const critical = Math.random() < this.critRate;
    const damage = critical ? Math.round(base * this.critMultiplier) : base;

    if (this.attackerIsPlayer) {
      this.botHp = Math.max(0, this.botHp - damage);
    } else {
      this.playerHp = Math.max(0, this.playerHp - damage);
    }
    this.updateHealthBars();
    console.log(
      (this.attackerIsPlayer ? "Player A" : "Bot B") +
      " hit for " + damage + (critical ? " critical damage" : "") +
      ". HP: Player " + this.playerHp + ", Bot " + this.botHp,
    );

    this.timer = 0;
    if (this.playerHp <= 0 || this.botHp <= 0) {
      const playerLost = this.playerHp <= 0;
      const deadImage = playerLost ? this.playerImage : this.botImage;
      this.playGif(deadImage, this.deadTex);
      this.resultText = playerLost ? "BOT WINS!" : "PLAYER WINS!";
      this.impactVisible = true;
      this.phase = "death";
      console.log((playerLost ? "Player A" : "Bot B") + " is defeated. " + this.resultText);
      return;
    }
    this.phase = "impact";
  }

  private finishImpact(): void {
    this.impactObj.setEnabledInHierarchy(false);
    this.impactVisible = false;
    if (this.attackerIsPlayer) {
      this.beginAttack(false);
      return;
    }
    this.turn += 1;
    this.startPreparation();
  }

  private tickDeath(dt: number): void {
    this.timer += dt;
    if (this.impactVisible && this.timer >= this.impactSec) {
      this.impactObj.setEnabledInHierarchy(false);
      this.impactVisible = false;
    }
    const resultDelay = Math.max(this.DEAD_ANIMATION_SEC, this.impactSec);
    if (this.timer >= resultDelay) {
      this.countdownLabel.text = this.resultText;
      this.countdownObj.setEnabledInHierarchy(true);
      this.retryObj.setEnabledInHierarchy(true);
      this.phase = "result";
      console.log(this.resultText);
    }
  }

  private updateHealthBars(): void {
    this.playerHealthImage.setMaterialProperty(
      "_filledRange",
      this.clamp(this.playerHp / this.maxHp, 0, 1),
    );
    this.botHealthImage.setMaterialProperty(
      "_filledRange",
      this.clamp(this.botHp / this.maxHp, 0, 1),
    );
  }

  private screenCenter(transform: APJS.ScreenTransform): APJS.Vector2f {
    const pos = transform.anchoredPosition;
    const size = transform.sizeDelta;
    const pivot = transform.pivot;
    return new APJS.Vector2f(
      pos.x + size.x * (0.5 - pivot.x),
      pos.y + size.y * (0.5 - pivot.y),
    );
  }

  private playGif(image: APJS.Image, texture: APJS.Texture): void {
    image.texture = texture;
    const provider = texture.getControl() as APJS.GifTextureProvider;
    provider.playFromStart();
  }

  private randomInt(min: number, max: number): number {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  private clamp(value: number, min: number, max: number): number {
    return Math.max(min, Math.min(max, value));
  }

  private clampInt(value: number, min: number, max: number): number {
    return Math.round(this.clamp(value, min, max));
  }
}

@component()
export class MageHitReaction extends APJS.BasicScriptComponent {
  @header("Theme & Assets")
  @serializeProperty
  @tooltip("One-shot animation shown when a Mage takes nonlethal damage.")
  private hitTex: APJS.Texture;

  @serializeProperty
  @tooltip("Idle animation restored after the hit reaction.")
  private idleTex: APJS.Texture;

  @header("Gameplay Tuning")
  @serializeProperty
  @tooltip("Seconds to show the hit reaction before returning to idle.")
  @slider(0.25, 1.5, 0.05)
  private hitDurationSec: number = 0.9;

  @header("Advanced — Scene Wiring")
  @serializeProperty
  @tooltip("Player Mage Image component.")
  private playerImage: APJS.Image;

  @serializeProperty
  @tooltip("Bot Mage Image component.")
  private botImage: APJS.Image;

  @serializeProperty
  @tooltip("Player health-fill Image, configured as Filled.")
  private playerHealthFill: APJS.Image;

  @serializeProperty
  @tooltip("Bot health-fill Image, configured as Filled.")
  private botHealthFill: APJS.Image;

  private ready = false;
  private hitProvider!: APJS.GifTextureProvider;
  private previousPlayerFill = 1;
  private previousBotFill = 1;
  private playerHitRemaining = 0;
  private botHitRemaining = 0;

  onLateUpdate(deltaTime: number): void {
    if (!this.ready) {
      if (!this.hitTex || !this.idleTex || !this.playerImage || !this.botImage ||
          !this.playerHealthFill || !this.botHealthFill) {
        return;
      }

      this.hitProvider = this.hitTex.getControl() as APJS.GifTextureProvider;
      this.previousPlayerFill = this.readHealth(this.playerHealthFill, 1);
      this.previousBotFill = this.readHealth(this.botHealthFill, 1);
      this.ready = true;
    }

    this.updateMage(this.playerImage, this.playerHealthFill, true, deltaTime);
    this.updateMage(this.botImage, this.botHealthFill, false, deltaTime);
  }

  private readHealth(fill: APJS.Image, fallback: number): number {
    const value = fill.getMaterialProperty("_filledRange");
    if (typeof value !== "number") return fallback;
    return Math.max(0, Math.min(1, value));
  }

  private updateMage(sprite: APJS.Image, fill: APJS.Image, isPlayer: boolean, deltaTime: number): void {
    const previous = isPlayer ? this.previousPlayerFill : this.previousBotFill;
    const current = this.readHealth(fill, previous);
    let remaining = isPlayer ? this.playerHitRemaining : this.botHitRemaining;

    if (current < previous - 0.001) {
      if (current > 0) {
        sprite.texture = this.hitTex;
        this.hitProvider.playFromStart();
        remaining = Math.max(0.25, Math.min(1.5, this.hitDurationSec));
      } else {
        // The existing BattleManager owns the fatal-hit death animation.
        remaining = 0;
      }
    }

    if (remaining > 0) {
      remaining = Math.max(0, remaining - deltaTime);
      if (remaining === 0 && current > 0) {
        const displayed = sprite.texture;
        if (displayed && displayed.name === this.hitTex.name) {
          sprite.texture = this.idleTex;
        }
      }
    }

    if (isPlayer) {
      this.previousPlayerFill = current;
      this.playerHitRemaining = remaining;
    } else {
      this.previousBotFill = current;
      this.botHitRemaining = remaining;
    }
  }
}

@component()
export class ImpactDirectionFlip extends APJS.BasicScriptComponent {
  @header("Advanced — Scene Wiring")
  @serializeProperty
  @tooltip("Projectile whose horizontal movement determines the impact direction.")
  projectileObject!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Screen transform used to sample the projectile's position.")
  projectileTransform!: APJS.ScreenTransform;

  @serializeProperty
  @tooltip("Impact effect object whose show event is detected.")
  impactObject!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Impact image mirrored when the projectile traveled left.")
  impactImage!: APJS.Image;

  private initialized: boolean = false;
  private projectileWasEnabled: boolean = false;
  private impactWasEnabled: boolean = false;
  private previousX: number = 0;
  private travelDirection: number = 1;

  onLateUpdate(_deltaTime: number): void {
    if (!this.projectileObject || !this.projectileTransform || !this.impactObject || !this.impactImage) {
      return;
    }

    const projectileEnabled = this.projectileObject.isEnabledInHierarchy();
    const impactEnabled = this.impactObject.isEnabledInHierarchy();
    const currentX = this.projectileTransform.anchoredPosition.x;

    if (!this.initialized) {
      this.previousX = currentX;
      this.projectileWasEnabled = projectileEnabled;
      this.impactWasEnabled = impactEnabled;
      this.initialized = true;
      return;
    }

    if (projectileEnabled) {
      if (!this.projectileWasEnabled) {
        // A newly enabled projectile may have teleported to its launch point.
        // Treat this as the baseline, then infer direction from later frames.
        this.previousX = currentX;
      } else {
        const deltaX = currentX - this.previousX;
        if (deltaX < -0.01) {
          this.travelDirection = -1;
        } else if (deltaX > 0.01) {
          this.travelDirection = 1;
        }
        this.previousX = currentX;
      }
    }

    if (impactEnabled && !this.impactWasEnabled) {
      // The art is authored left-to-right; mirror it only for a leftward shot.
      this.impactImage.flipX = this.travelDirection < 0;
    }

    this.projectileWasEnabled = projectileEnabled;
    this.impactWasEnabled = impactEnabled;
  }
}

@component()
export class ImpactDirectionPresentation extends APJS.BasicScriptComponent {
  @header("Gameplay Tuning")
  @serializeProperty
  @tooltip("Screen-pixel offset that places the impact slightly behind the projectile.")
  @slider(0, 32, 1)
  behindOffsetPixels: number = 12;

  @header("Advanced — Scene Wiring")
  @serializeProperty
  projectileObject!: APJS.SceneObject;

  @serializeProperty
  projectileTransform!: APJS.ScreenTransform;

  @serializeProperty
  impactObject!: APJS.SceneObject;

  @serializeProperty
  impactTransform!: APJS.ScreenTransform;

  @serializeProperty
  impactImage!: APJS.Image;

  private initialized: boolean = false;
  private projectileWasEnabled: boolean = false;
  private impactWasEnabled: boolean = false;
  private previousX: number = 0;
  private travelDirection: number = 1;

  onLateUpdate(_deltaTime: number): void {
    if (!this.projectileObject || !this.projectileTransform || !this.impactObject ||
        !this.impactTransform || !this.impactImage) {
      return;
    }

    const projectileEnabled = this.projectileObject.isEnabledInHierarchy();
    const impactEnabled = this.impactObject.isEnabledInHierarchy();
    const currentX = this.projectileTransform.anchoredPosition.x;

    if (!this.initialized) {
      this.previousX = currentX;
      this.projectileWasEnabled = projectileEnabled;
      this.impactWasEnabled = impactEnabled;
      this.initialized = true;
      return;
    }

    if (projectileEnabled) {
      if (!this.projectileWasEnabled) {
        // The projectile may have teleported to its launch point this frame.
        this.previousX = currentX;
      } else {
        const deltaX = currentX - this.previousX;
        if (deltaX < -0.01) {
          this.travelDirection = -1;
        } else if (deltaX > 0.01) {
          this.travelDirection = 1;
        }
        this.previousX = currentX;
      }
    }

    if (impactEnabled && !this.impactWasEnabled) {
      this.impactImage.flipX = this.travelDirection < 0;

      const impactPosition = this.impactTransform.anchoredPosition;
      const offset = Math.max(0, Math.min(32, this.behindOffsetPixels));
      this.impactTransform.anchoredPosition = new APJS.Vector2f(
        impactPosition.x - this.travelDirection * offset,
        impactPosition.y
      );
    }

    this.projectileWasEnabled = projectileEnabled;
    this.impactWasEnabled = impactEnabled;
  }
}

@component()
export class ImpactDirectionPresentation extends APJS.BasicScriptComponent {
  @header("Gameplay Tuning")
  @serializeProperty
  @tooltip("Screen-pixel offset behind the projectile when the impact effect appears.")
  @slider(0, 128, 1)
  behindOffsetPixels: number = 100;

  @header("Advanced — Scene Wiring")
  @serializeProperty
  projectileObject!: APJS.SceneObject;

  @serializeProperty
  projectileTransform!: APJS.ScreenTransform;

  @serializeProperty
  impactObject!: APJS.SceneObject;

  @serializeProperty
  impactTransform!: APJS.ScreenTransform;

  @serializeProperty
  impactImage!: APJS.Image;

  private initialized: boolean = false;
  private projectileWasEnabled: boolean = false;
  private impactWasEnabled: boolean = false;
  private previousX: number = 0;
  private travelDirection: number = 1;

  onLateUpdate(_deltaTime: number): void {
    if (!this.projectileObject || !this.projectileTransform || !this.impactObject ||
        !this.impactTransform || !this.impactImage) {
      return;
    }

    const projectileEnabled = this.projectileObject.isEnabledInHierarchy();
    const impactEnabled = this.impactObject.isEnabledInHierarchy();
    const currentX = this.projectileTransform.anchoredPosition.x;

    if (!this.initialized) {
      this.previousX = currentX;
      this.projectileWasEnabled = projectileEnabled;
      this.impactWasEnabled = impactEnabled;
      this.initialized = true;
      return;
    }

    if (projectileEnabled) {
      if (!this.projectileWasEnabled) {
        this.previousX = currentX;
      } else {
        const deltaX = currentX - this.previousX;
        if (deltaX < -0.01) {
          this.travelDirection = -1;
        } else if (deltaX > 0.01) {
          this.travelDirection = 1;
        }
        this.previousX = currentX;
      }
    }

    if (impactEnabled && !this.impactWasEnabled) {
      this.impactImage.flipX = this.travelDirection < 0;

      const impactPosition = this.impactTransform.anchoredPosition;
      const offset = Math.max(0, Math.min(128, this.behindOffsetPixels));
      this.impactTransform.anchoredPosition = new APJS.Vector2f(
        impactPosition.x - this.travelDirection * offset,
        impactPosition.y
      );
    }

    this.projectileWasEnabled = projectileEnabled;
    this.impactWasEnabled = impactEnabled;
  }
}

@component()
export class DamagePopupManager extends APJS.BasicScriptComponent {
  @header("Advanced — Scene Wiring")
  @serializeProperty
  @tooltip("Player health fill; a decrease triggers the player's damage popup.")
  private playerHealthFill!: APJS.Image;

  @serializeProperty
  @tooltip("Bot health fill; a decrease triggers the bot's damage popup.")
  private botHealthFill!: APJS.Image;

  @serializeProperty
  @tooltip("Hidden Text object positioned above the player.")
  private playerPopup!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Text component used for the player's damage number.")
  private playerText!: APJS.Text;

  @serializeProperty
  @tooltip("ScreenTransform used to animate the player's damage number.")
  private playerPopupTransform!: APJS.ScreenTransform;

  @serializeProperty
  @tooltip("Hidden Text object positioned above the bot.")
  private botPopup!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Text component used for the bot's damage number.")
  private botText!: APJS.Text;

  @serializeProperty
  @tooltip("ScreenTransform used to animate the bot's damage number.")
  private botPopupTransform!: APJS.ScreenTransform;

  private static readonly MAX_HP: number = 100;
  private static readonly NORMAL_MAX_DAMAGE: number = 15;
  private static readonly POPUP_DURATION_SEC: number = 1;
  private static readonly RISE_DISTANCE_PX: number = 44;
  private static readonly NORMAL_FONT_SIZE: number = 46;
  private static readonly CRIT_FONT_SIZE: number = 64;

  private playerPreviousFill: number = 1;
  private botPreviousFill: number = 1;
  private playerBaseX: number = 0;
  private playerBaseY: number = 155;
  private botBaseX: number = 0;
  private botBaseY: number = 155;
  private playerPopupElapsed: number = -1;
  private botPopupElapsed: number = -1;

  onStart(): void {
    this.playerPreviousFill = this.readFill(this.playerHealthFill);
    this.botPreviousFill = this.readFill(this.botHealthFill);

    const playerPosition = this.playerPopupTransform.anchoredPosition;
    this.playerBaseX = playerPosition.x;
    this.playerBaseY = playerPosition.y;
    const botPosition = this.botPopupTransform.anchoredPosition;
    this.botBaseX = botPosition.x;
    this.botBaseY = botPosition.y;

    this.playerPopup.setEnabledInHierarchy(false);
    this.botPopup.setEnabledInHierarchy(false);
    this.playerText.text = "";
    this.botText.text = "";
  }

  onLateUpdate(deltaTime: number): void {
    const playerFill = this.readFill(this.playerHealthFill);
    const botFill = this.readFill(this.botHealthFill);

    const playerDamage = Math.round((this.playerPreviousFill - playerFill) * DamagePopupManager.MAX_HP);
    if (playerDamage > 0) {
      this.showPopup(playerDamage, this.playerPopup, this.playerText, this.playerPopupTransform, this.playerBaseX, this.playerBaseY);
    }

    const botDamage = Math.round((this.botPreviousFill - botFill) * DamagePopupManager.MAX_HP);
    if (botDamage > 0) {
      this.showPopup(botDamage, this.botPopup, this.botText, this.botPopupTransform, this.botBaseX, this.botBaseY);
    }

    this.playerPreviousFill = playerFill;
    this.botPreviousFill = botFill;

    this.playerPopupElapsed = this.advancePopup(
      deltaTime, this.playerPopupElapsed, this.playerPopup, this.playerPopupTransform, this.playerBaseX, this.playerBaseY
    );
    this.botPopupElapsed = this.advancePopup(
      deltaTime, this.botPopupElapsed, this.botPopup, this.botPopupTransform, this.botBaseX, this.botBaseY
    );
  }

  private readFill(image: APJS.Image): number {
    const value = image.getMaterialProperty("_filledRange");
    return typeof value === "number" ? value : 1;
  }

  private showPopup(
    damage: number,
    popup: APJS.SceneObject,
    text: APJS.Text,
    transform: APJS.ScreenTransform,
    baseX: number,
    baseY: number
  ): void {
    const isCrit = damage > DamagePopupManager.NORMAL_MAX_DAMAGE;
    text.text = "-" + damage.toString();
    text.color = isCrit
      ? new APJS.Color(1, 0.52, 0.02, 1)
      : new APJS.Color(1, 1, 1, 1);
    text.fontSize = isCrit
      ? DamagePopupManager.CRIT_FONT_SIZE
      : DamagePopupManager.NORMAL_FONT_SIZE;
    text.opacity = 1;
    transform.anchoredPosition = new APJS.Vector2f(baseX, baseY);
    popup.setEnabledInHierarchy(true);

    if (popup === this.playerPopup) {
      this.playerPopupElapsed = 0;
    } else {
      this.botPopupElapsed = 0;
    }
  }

  private advancePopup(
    deltaTime: number,
    elapsed: number,
    popup: APJS.SceneObject,
    transform: APJS.ScreenTransform,
    baseX: number,
    baseY: number
  ): number {
    if (elapsed < 0) {
      return -1;
    }

    elapsed += deltaTime;
    const progress = Math.min(elapsed / DamagePopupManager.POPUP_DURATION_SEC, 1);
    const eased = 1 - (1 - progress) * (1 - progress);
    transform.anchoredPosition = new APJS.Vector2f(
      baseX,
      baseY + DamagePopupManager.RISE_DISTANCE_PX * eased
    );

    if (elapsed >= DamagePopupManager.POPUP_DURATION_SEC) {
      popup.setEnabledInHierarchy(false);
      transform.anchoredPosition = new APJS.Vector2f(baseX, baseY);
      return -1;
    }

    return elapsed;
  }
}

@component()
export class ProjectileSpawnOffset extends APJS.BasicScriptComponent {
  @serializeProperty
  projectileObj: APJS.SceneObject;

  @serializeProperty
  playerObj: APJS.SceneObject;

  @serializeProperty
  botObj: APJS.SceneObject;

  private active: boolean = false;
  private wasEnabled: boolean = false;
  private startX: number = 0;
  private startY: number = 0;
  private targetX: number = 0;
  private targetY: number = 0;
  private offsetX: number = 0;
  private offsetY: number = 0;
  private lastBaseX: number = 0;
  private lastBaseY: number = 0;
  private lastOutputX: number = 0;
  private lastOutputY: number = 0;

  onLateUpdate(_deltaTime: number): void {
    if (!this.projectileObj || !this.playerObj || !this.botObj) {
      return;
    }

    const enabled = this.projectileObj.enabled;
    if (!enabled) {
      this.wasEnabled = false;
      this.active = false;
      return;
    }

    const projectileTransform = this.projectileObj.getComponent("ScreenTransform") as APJS.ScreenTransform | null;
    if (!projectileTransform) {
      return;
    }

    if (!this.wasEnabled) {
      this.wasEnabled = true;
      this.beginSpawn(projectileTransform);
      return;
    }

    if (!this.active) {
      return;
    }

    const current = projectileTransform.anchoredPosition;
    let baseX = current.x;
    let baseY = current.y;

    // If the manager left the projectile untouched this frame, undo our previous
    // visual correction before applying the new correction.
    if (Math.abs(current.x - this.lastOutputX) < 0.5 &&
        Math.abs(current.y - this.lastOutputY) < 0.5) {
      baseX = this.lastBaseX;
      baseY = this.lastBaseY;
    }

    this.applyCorrection(projectileTransform, baseX, baseY);
  }

  private beginSpawn(projectileTransform: APJS.ScreenTransform): void {
    const playerTransform = this.playerObj.getComponent("ScreenTransform") as APJS.ScreenTransform | null;
    const botTransform = this.botObj.getComponent("ScreenTransform") as APJS.ScreenTransform | null;
    if (!playerTransform || !botTransform) {
      return;
    }

    const spawn = projectileTransform.anchoredPosition;
    const player = playerTransform.anchoredPosition;
    const bot = botTransform.anchoredPosition;
    const dxPlayer = spawn.x - player.x;
    const dyPlayer = spawn.y - player.y;
    const dxBot = spawn.x - bot.x;
    const dyBot = spawn.y - bot.y;
    const playerDistanceSq = dxPlayer * dxPlayer + dyPlayer * dyPlayer;
    const botDistanceSq = dxBot * dxBot + dyBot * dyBot;
    const playerIsAttacker = playerDistanceSq <= botDistanceSq;
    const attackerTransform = playerIsAttacker ? playerTransform : botTransform;
    const targetTransform = playerIsAttacker ? botTransform : playerTransform;

    const characterSize = attackerTransform.sizeDelta;
    const targetPosition = targetTransform.anchoredPosition;
    this.startX = spawn.x;
    this.startY = spawn.y;
    this.targetX = targetPosition.x;
    this.targetY = targetPosition.y;
    this.offsetX = (playerIsAttacker ? 1 : -1) * characterSize.x * 0.5;
    this.offsetY = characterSize.y * 0.2;
    this.lastBaseX = spawn.x;
    this.lastBaseY = spawn.y;
    this.active = true;

    this.applyCorrection(projectileTransform, spawn.x, spawn.y);
  }

  private applyCorrection(
    projectileTransform: APJS.ScreenTransform,
    baseX: number,
    baseY: number
  ): void {
    const pathX = this.targetX - this.startX;
    const pathY = this.targetY - this.startY;
    const pathLengthSq = pathX * pathX + pathY * pathY;
    let progress = 0;

    if (pathLengthSq > 0.001) {
      const traveledX = baseX - this.startX;
      const traveledY = baseY - this.startY;
      progress = (traveledX * pathX + traveledY * pathY) / pathLengthSq;
      progress = Math.max(0, Math.min(1, progress));
    }

    const remaining = 1 - progress;
    const outputX = baseX + this.offsetX * remaining;
    const outputY = baseY + this.offsetY * remaining;
    projectileTransform.anchoredPosition = new APJS.Vector2f(outputX, outputY);
    this.lastBaseX = baseX;
    this.lastBaseY = baseY;
    this.lastOutputX = outputX;
    this.lastOutputY = outputY;
  }
}

