@component()
export class ProjectileSpawnOffset extends APJS.BasicScriptComponent {
  @serializeProperty
  projectileObj: APJS.SceneObject;

  @serializeProperty
  playerObj: APJS.SceneObject;

  @serializeProperty
  botObj: APJS.SceneObject;

  private spawnInitialized: boolean = false;
  private flightStarted: boolean = false;
  private attackerIsPlayer: boolean = true;
  private startX: number = 0;
  private startY: number = 0;
  private targetX: number = 0;
  private targetY: number = 0;
  private offsetX: number = 0;
  private offsetY: number = 0;
  private managerBaseX: number = 0;
  private managerBaseY: number = 0;
  private displayedX: number = 0;
  private displayedY: number = 0;
  private flightElapsed: number = 0;
  private readonly flightDurationSec: number = 0.5;

  onEnable(): void {
    this.resetState();
  }

  onDisable(): void {
    this.resetState();
  }

  onLateUpdate(deltaTime: number): void {
    if (!this.projectileObj || !this.playerObj || !this.botObj) {
      return;
    }

    const projectileTransform = this.projectileObj.getComponent("ScreenTransform") as APJS.ScreenTransform | null;
    if (!projectileTransform) {
      return;
    }

    if (!this.projectileObj.enabled) {
      this.resetState();
      return;
    }

    const current = projectileTransform.anchoredPosition;
    if (!this.spawnInitialized) {
      this.beginSpawn(projectileTransform, current.x, current.y);
      return;
    }

    if (this.flightStarted) {
      this.advanceFlight(projectileTransform, deltaTime);
      return;
    }

    // During charge, the manager can leave our last visual position in place
    // or write its unshifted base position again. Recover that base without
    // moving the visible projectile back to it.
    const isPreviousOutput =
      Math.abs(current.x - this.displayedX) < 0.5 &&
      Math.abs(current.y - this.displayedY) < 0.5;
    const baseX = isPreviousOutput ? this.managerBaseX : current.x;
    const baseY = isPreviousOutput ? this.managerBaseY : current.y;

    const movedX = baseX - this.managerBaseX;
    const movedY = baseY - this.managerBaseY;
    if (movedX * movedX + movedY * movedY > 0.25) {
      // The manager's path has begun moving. Start our flight from the exact
      // position WaterBall held at the end of its charge, not from the mage.
      this.flightStarted = true;
      this.startX = this.displayedX;
      this.startY = this.displayedY;
      this.flightElapsed = Math.max(0, deltaTime);
      this.advanceFlight(projectileTransform, 0);
      return;
    }

    this.managerBaseX = baseX;
    this.managerBaseY = baseY;
    this.writePosition(
      projectileTransform,
      baseX + this.offsetX,
      baseY + this.offsetY
    );
  }

  private beginSpawn(
    projectileTransform: APJS.ScreenTransform,
    baseX: number,
    baseY: number
  ): void {
    const playerTransform = this.playerObj.getComponent("ScreenTransform") as APJS.ScreenTransform | null;
    const botTransform = this.botObj.getComponent("ScreenTransform") as APJS.ScreenTransform | null;
    if (!playerTransform || !botTransform) {
      return;
    }

    const player = playerTransform.anchoredPosition;
    const bot = botTransform.anchoredPosition;
    const dxPlayer = baseX - player.x;
    const dyPlayer = baseY - player.y;
    const dxBot = baseX - bot.x;
    const dyBot = baseY - bot.y;
    this.attackerIsPlayer =
      dxPlayer * dxPlayer + dyPlayer * dyPlayer <=
      dxBot * dxBot + dyBot * dyBot;

    const attackerTransform = this.attackerIsPlayer ? playerTransform : botTransform;
    const targetTransform = this.attackerIsPlayer ? botTransform : playerTransform;
    const characterSize = attackerTransform.sizeDelta;
    const target = targetTransform.anchoredPosition;

    this.managerBaseX = baseX;
    this.managerBaseY = baseY;
    this.targetX = target.x;
    this.targetY = target.y;
    this.offsetX =
      (this.attackerIsPlayer ? 1 : -1) *
      Math.max(0, characterSize.x * 0.5 - 30);
    this.offsetY = characterSize.y * 0.2;
    this.spawnInitialized = true;
    this.writePosition(
      projectileTransform,
      baseX + this.offsetX,
      baseY + this.offsetY
    );
  }

  private advanceFlight(
    projectileTransform: APJS.ScreenTransform,
    deltaTime: number
  ): void {
    this.flightElapsed = Math.min(
      this.flightDurationSec,
      this.flightElapsed + deltaTime
    );
    const progress = Math.max(
      0,
      Math.min(1, this.flightElapsed / this.flightDurationSec)
    );
    const x = this.startX + (this.targetX - this.startX) * progress;
    const y = this.startY + (this.targetY - this.startY) * progress;
    this.writePosition(projectileTransform, x, y);
  }

  private writePosition(
    projectileTransform: APJS.ScreenTransform,
    x: number,
    y: number
  ): void {
    projectileTransform.anchoredPosition = new APJS.Vector2f(x, y);
    this.displayedX = x;
    this.displayedY = y;
  }

  private resetState(): void {
    this.spawnInitialized = false;
    this.flightStarted = false;
    this.flightElapsed = 0;
  }
}

