    const player = playerTransform.anchoredPosition;
    const bot = botTransform.anchoredPosition;
    const dxPlayer = baseX - player.x;
    const dyPlayer = baseY - player.y;
    const dxBot = baseX - bot.x;
    const dyBot = baseY - bot.y;
    const playerIsAttacker =
      dxPlayer * dxPlayer + dyPlayer * dyPlayer <=
      dxBot * dxBot + dyBot * dyBot;

    const attackerTransform = playerIsAttacker ? playerTransform : botTransform;
    const targetTransform = playerIsAttacker ? botTransform : playerTransform;
    const characterSize = attackerTransform.sizeDelta;
    const target = targetTransform.anchoredPosition;

    this.managerBaseX = baseX;
    this.managerBaseY = baseY;
    this.targetX = target.x;
    this.targetY = target.y;
    this.offsetX =
      (playerIsAttacker ? 1 : -1) *
      Math.max(0, characterSize.x * 0.5 - 30);
    this.offsetY = characterSize.y * 0.2;
    this.phase = 1;
    this.writePosition(
      projectileTransform,
      baseX + this.offsetX,
      baseY + this.offsetY
    );
  }

  private advanceFlight(
    projectileTransform: APJS.ScreenTransform,
    deltaTime: number
  ): void {
    this.flightElapsed = Math.min(
      this.flightDurationSec,
      this.flightElapsed + deltaTime
    );
    const progress = Math.max(
      0,
      Math.min(1, this.flightElapsed / this.flightDurationSec)
    );
    const x = this.startX + (this.targetX - this.startX) * progress;
    const y = this.startY + (this.targetY - this.startY) * progress;
    this.writePosition(projectileTransform, x, y);
  }

  private writePosition(
    projectileTransform: APJS.ScreenTransform,
    x: number,
    y: number
  ): void {
    projectileTransform.anchoredPosition = new APJS.Vector2f(x, y);
    this.displayedX = x;
    this.displayedY = y;
  }

  private resetState(): void {
    this.phase = 0;
    this.disabledDuration = 0;
    this.flightElapsed = 0;
  }
}

@component()
export class ImpactPivotByDirection extends APJS.BasicScriptComponent {
  @serializeProperty
  projectileObj: APJS.SceneObject;

  @serializeProperty
  impactTransform: APJS.ScreenTransform;

  private wasTracking: boolean = false;
  private lastX: number = 0;
  private lastY: number = 0;

  onLateUpdate(_deltaTime: number): void {
    if (!this.projectileObj || !this.impactTransform) {
      return;
    }

    if (!this.projectileObj.enabled) {
      this.wasTracking = false;
      return;
    }

    const projectileTransform = this.projectileObj.getComponent("ScreenTransform") as APJS.ScreenTransform | null;
    if (!projectileTransform) {
      return;
    }

    const position = projectileTransform.anchoredPosition;
    if (!this.wasTracking) {
      this.lastX = position.x;
      this.lastY = position.y;
      this.wasTracking = true;
      return;
    }

    const dx = position.x - this.lastX;
    if (Math.abs(dx) > 0.5) {
      const currentPivot = this.impactTransform.pivot;
      const pivotX = dx > 0 ? 0.75 : 0.25;
      this.impactTransform.pivot = new APJS.Vector2f(pivotX, currentPivot.y);
    }

    this.lastX = position.x;
    this.lastY = position.y;
  }
}

@component()
export class BattleButtonFeedback extends APJS.BasicScriptComponent {
  @serializeProperty
  attackButtonObj: APJS.SceneObject;

  @serializeProperty
  defenseButtonObj: APJS.SceneObject;

  private initialized: boolean = false;
  private pressedButton: "attack" | "defense" | null = null;
  private attackImage!: APJS.Image;
  private defenseImage!: APJS.Image;
  private attackTransform!: APJS.ScreenTransform;
  private defenseTransform!: APJS.ScreenTransform;
  private attackBaseScale!: APJS.Vector2f;
  private defenseBaseScale!: APJS.Vector2f;

  private onTouch = (event: APJS.IEvent): void => {
    if (!this.initialized) {
      return;
    }

    const touchInfo = event.args[0] as APJS.TouchData;

    if (touchInfo.phase === APJS.TouchPhase.Began) {
      if (this.pressedButton !== null) {
        return;
      }

      if (APJS.TouchUtils.isScreenPointOnImage(touchInfo.position, this.defenseImage)) {
        this.pressedButton = "defense";
        this.setButtonVisual("defense", true);
      } else if (APJS.TouchUtils.isScreenPointOnImage(touchInfo.position, this.attackImage)) {
        this.pressedButton = "attack";
        this.setButtonVisual("attack", true);
      }
      return;
    }

    if (this.pressedButton === null) {
      return;
    }

    if (touchInfo.phase === APJS.TouchPhase.Moved) {
      const inside = this.isInsidePressedButton(touchInfo.position);
      this.setButtonVisual(this.pressedButton, inside);
      return;
    }

    if (touchInfo.phase === APJS.TouchPhase.Ended) {
      const button = this.pressedButton;
      const clickedInside = this.isInsidePressedButton(touchInfo.position);
      this.setButtonVisual(button, false);
      this.pressedButton = null;

      if (clickedInside && button === "attack") {
        console.log("[Battle UI] Attack_Button clicked");
      } else if (clickedInside && button === "defense") {
        console.log("[Battle UI] Defense_Button clicked");
      }
      return;
    }

    if (touchInfo.phase === APJS.TouchPhase.Canceled) {
      this.setButtonVisual(this.pressedButton, false);
      this.pressedButton = null;
    }
  };

  onUpdate(_deltaTime: number): void {
    if (this.initialized || !this.attackButtonObj || !this.defenseButtonObj) {
      return;
    }

    const attackImage = this.attackButtonObj.getComponent("Image") as APJS.Image | null;
    const defenseImage = this.defenseButtonObj.getComponent("Image") as APJS.Image | null;
    const attackTransform = this.attackButtonObj.getComponent("ScreenTransform") as APJS.ScreenTransform | null;
    const defenseTransform = this.defenseButtonObj.getComponent("ScreenTransform") as APJS.ScreenTransform | null;

    if (!attackImage || !defenseImage || !attackTransform || !defenseTransform) {
      console.error("[Battle UI] Button image or transform is missing");
      return;
    }

    this.attackImage = attackImage;
    this.defenseImage = defenseImage;
    this.attackTransform = attackTransform;
    this.defenseTransform = defenseTransform;
    const attackScale = attackTransform.scale;
    const defenseScale = defenseTransform.scale;
    this.attackBaseScale = new APJS.Vector2f(attackScale.x, attackScale.y);
    this.defenseBaseScale = new APJS.Vector2f(defenseScale.x, defenseScale.y);

    APJS.EventManager.getGlobalEmitter().on(APJS.EventType.Touch, this.onTouch);
    this.initialized = true;
    console.log("[Battle UI] Attack_Button and Defense_Button input ready");
  }

  private isInsidePressedButton(position: APJS.Vector2f): boolean {
    if (this.pressedButton === "attack") {
      return APJS.TouchUtils.isScreenPointOnImage(position, this.attackImage);
    }
    if (this.pressedButton === "defense") {
      return APJS.TouchUtils.isScreenPointOnImage(position, this.defenseImage);
    }
    return false;
  }

  private setButtonVisual(button: "attack" | "defense", pressed: boolean): void {
    const tint = pressed
      ? new APJS.Color(0.68, 0.68, 0.68, 1)
      : new APJS.Color(1, 1, 1, 1);
    const factor = pressed ? 0.9 : 1;

    if (button === "attack") {
      this.attackImage.color = tint;
      this.attackTransform.scale = new APJS.Vector2f(
        this.attackBaseScale.x * factor,
        this.attackBaseScale.y * factor
      );
    } else {
      this.defenseImage.color = tint;
      this.defenseTransform.scale = new APJS.Vector2f(
        this.defenseBaseScale.x * factor,
        this.defenseBaseScale.y * factor
      );
    }
  }

  onDestroy(): void {
    if (this.initialized) {
      APJS.EventManager.getGlobalEmitter().off(APJS.EventType.Touch, this.onTouch);
    }
  }
}

