@component()
export class PlayerCharacter extends APJS.BasicScriptComponent {
  @header("Player Skill Buttons")
  @serializeProperty
  @tooltip("Attack skill button monitored by this player controller.")
  attackButtonObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Defense skill button monitored by this player controller.")
  defenseButtonObj!: APJS.SceneObject;

  private static readonly SKILL_ATTACK: number = 1;
  private static readonly SKILL_DEFENSE: number = 2;
  private attackImage!: APJS.Image;
  private defenseImage!: APJS.Image;
  private skillRequestType!: APJS.UserEventType;
  private attackPressed: boolean = false;
  private defensePressed: boolean = false;
  private eventsBound: boolean = false;

  private onTouch = (event: APJS.IEvent): void => {
    const touch = event.args[0] as APJS.TouchData;
    if (touch.phase === APJS.TouchPhase.Began) {
      this.attackPressed = APJS.TouchUtils.isScreenPointOnImage(touch.position, this.attackImage);
      this.defensePressed = APJS.TouchUtils.isScreenPointOnImage(touch.position, this.defenseImage);
      return;
    }
    if (touch.phase === APJS.TouchPhase.Ended) {
      const useAttack = this.attackPressed && APJS.TouchUtils.isScreenPointOnImage(touch.position, this.attackImage);
      const useDefense = this.defensePressed && APJS.TouchUtils.isScreenPointOnImage(touch.position, this.defenseImage);
      this.attackPressed = false;
      this.defensePressed = false;
      if (useAttack) this.requestSkill(PlayerCharacter.SKILL_ATTACK);
      if (useDefense) this.requestSkill(PlayerCharacter.SKILL_DEFENSE);
      return;
    }
    if (touch.phase === APJS.TouchPhase.Canceled) {
      this.attackPressed = false;
      this.defensePressed = false;
    }
  };

  onStart(): void {
    if (!this.attackButtonObj || !this.defenseButtonObj) {
      console.error("[PlayerCharacter] Skill button references are missing.");
      return;
    }
    this.attackImage = this.attackButtonObj.getComponent("Image") as APJS.Image;
    this.defenseImage = this.defenseButtonObj.getComponent("Image") as APJS.Image;
    if (!this.attackImage || !this.defenseImage) {
      console.error("[PlayerCharacter] Skill buttons need Image components.");
      return;
    }
    this.skillRequestType = APJS.EventManager.defineUserEventType("battle.player.skill_request");
    APJS.EventManager.getGlobalEmitter().on(APJS.EventType.Touch, this.onTouch, this);
    this.eventsBound = true;
  }

  private requestSkill(skill: number): void {
    const event = APJS.EventManager.createEvent(this.skillRequestType);
    event.args = [skill];
    APJS.EventManager.getGlobalEmitter().emit(event);
  }

  onDestroy(): void {
    if (this.eventsBound) {
      APJS.EventManager.getGlobalEmitter().off(APJS.EventType.Touch, this.onTouch, this);
    }
  }
}

@component()
export class BotCharacter extends APJS.BasicScriptComponent {
  private static readonly NO_SKILL: number = 0;
  private static readonly ATTACK_SKILL: number = 1;
  private static readonly DEFENSE_SKILL: number = 2;
  private static readonly BOTH_SKILLS: number = 3;

  public chooseSkills(playerHp: number, botHp: number, botMana: number, maxHp: number, attackCost: number, defenseCost: number): number {
    const botHpIsLow = botHp <= maxHp * 0.75;
    if (botMana <= 5 && (!botHpIsLow || botMana < attackCost)) {
      return BotCharacter.NO_SKILL;
    }

    let skillChance = 1;
    if (!botHpIsLow) {
      if (botMana === 6) skillChance = 0.25;
      else if (botMana === 7) skillChance = 0.45;
      else if (botMana === 8) skillChance = 0.65;
      else if (botMana === 9) skillChance = 0.85;
    }
    if (Math.random() >= skillChance) return BotCharacter.NO_SKILL;

    if (botMana >= attackCost + defenseCost && Math.random() < 0.35) {
      return BotCharacter.BOTH_SKILLS;
    }

    let chooseDefense = false;
    if (botHpIsLow) {
      if (playerHp > botHp) chooseDefense = Math.random() < 0.65;
      else if (botHp > playerHp) chooseDefense = Math.random() < 0.35;
      else chooseDefense = Math.random() < 0.5;
    } else {
      chooseDefense = botHp < playerHp;
    }

    if (chooseDefense && botMana >= defenseCost) return BotCharacter.DEFENSE_SKILL;
    if (botMana >= attackCost) return BotCharacter.ATTACK_SKILL;
    return BotCharacter.NO_SKILL;
  }
}

@component()
export class UIManager extends APJS.BasicScriptComponent {
  @header("UI Scene Wiring")
  @serializeProperty
  @tooltip("Player attack skill button.")
  attackButtonObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Player defense skill button.")
  defenseButtonObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Current turn label.")
  turnObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Countdown and winner callout label.")
  countdownObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Retry button shown after the result animation.")
  retryObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Button that skips the preparation countdown.")
  fightNowObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Winner HP label shown in the result state.")
  resultHpLabelObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Animated winner HP percentage label.")
  resultHpPercentObj!: APJS.SceneObject;

  @serializeProperty
  @tooltip("Positive chime played while the result percentage counts.")
  resultChimeObj!: APJS.SceneObject;

  private static readonly RESULT_CHIME_STEP: number = 10;
  private ready: boolean = false;
  private retryVisible: boolean = false;
  private fightNowVisible: boolean = false;
  private resultTweenActive: boolean = false;
  private resultTweenTimer: number = 0;
  private resultTargetPercent: number = 0;
  private lastChimePercent: number = 100;
  private resultCompleteType!: APJS.UserEventType;
  private attackImage!: APJS.Image;
  private defenseImage!: APJS.Image;
  private turnLabel!: APJS.Text;
  private countdownLabel!: APJS.Text;
  private retryImage!: APJS.Image;
  private fightNowImage!: APJS.Image;
  private resultHpLabelText!: APJS.Text;
  private resultHpPercentText!: APJS.Text;
  private resultChimeAudio!: APJS.AudioComponent;

  onStart(): void {
    if (!this.attackButtonObj || !this.defenseButtonObj || !this.turnObj || !this.countdownObj ||
        !this.retryObj || !this.fightNowObj || !this.resultHpLabelObj || !this.resultHpPercentObj || !this.resultChimeObj) {
      console.error("[UIManager] One or more UI references are missing.");
      return;
    }
    this.attackImage = this.attackButtonObj.getComponent("Image") as APJS.Image;
    this.defenseImage = this.defenseButtonObj.getComponent("Image") as APJS.Image;
    this.turnLabel = this.turnObj.getComponent("Text") as APJS.Text;
    this.countdownLabel = this.countdownObj.getComponent("Text") as APJS.Text;
    this.retryImage = this.retryObj.getComponent("Image") as APJS.Image;
    this.fightNowImage = this.fightNowObj.getComponent("Image") as APJS.Image;
    this.resultHpLabelText = this.resultHpLabelObj.getComponent("Text") as APJS.Text;
    this.resultHpPercentText = this.resultHpPercentObj.getComponent("Text") as APJS.Text;
    this.resultChimeAudio = this.resultChimeObj.getComponent("AudioComponent") as APJS.AudioComponent;
    if (!this.attackImage || !this.defenseImage || !this.turnLabel || !this.countdownLabel ||
        !this.retryImage || !this.fightNowImage || !this.resultHpLabelText || !this.resultHpPercentText || !this.resultChimeAudio) {
      console.error("[UIManager] A wired UI object is missing its required component.");
      return;
    }
    this.resultCompleteType = APJS.EventManager.defineUserEventType("battle.ui.result_complete");
    this.ready = true;
  }

  public isAttackButtonAt(position: APJS.Vector2f): boolean {
    return this.ready && APJS.TouchUtils.isScreenPointOnImage(position, this.attackImage);
  }

  public isDefenseButtonAt(position: APJS.Vector2f): boolean {
    return this.ready && APJS.TouchUtils.isScreenPointOnImage(position, this.defenseImage);
  }

  public isRetryButtonAt(position: APJS.Vector2f): boolean {
    return this.ready && this.retryVisible && APJS.TouchUtils.isScreenPointOnImage(position, this.retryImage);
  }

  public isFightNowButtonAt(position: APJS.Vector2f): boolean {
    return this.ready && this.fightNowVisible && APJS.TouchUtils.isScreenPointOnImage(position, this.fightNowImage);
  }

  public setTurn(turn: number): void {
    if (this.ready) this.turnLabel.text = "Turn " + String(turn);
  }

  public setCountdown(text: string, fontSize: number): void {
    if (!this.ready) return;
    this.countdownLabel.text = text;
    this.countdownLabel.fontSize = fontSize;
  }

  public setCountdownVisible(visible: boolean): void {
    if (this.ready) this.countdownObj.setEnabledInHierarchy(visible);
  }

  public setSkillButtonsVisible(visible: boolean): void {
    if (!this.ready) return;
    this.attackButtonObj.setEnabledInHierarchy(visible);
    this.defenseButtonObj.setEnabledInHierarchy(visible);
  }

  public setAttackAvailable(available: boolean): void {
    if (this.ready) this.attackImage.opacity = available ? 1 : 0.4;
  }

  public setDefenseAvailable(available: boolean): void {
    if (this.ready) this.defenseImage.opacity = available ? 1 : 0.4;
  }

  public setFightNowVisible(visible: boolean): void {
    if (!this.ready) return;
    this.fightNowVisible = visible;
    this.fightNowObj.setEnabledInHierarchy(visible);
  }

  public setRetryVisible(visible: boolean): void {
    if (!this.ready) return;
    this.retryVisible = visible;
    this.retryObj.setEnabledInHierarchy(visible);
  }

  public resetResult(): void {
    if (!this.ready) return;
    this.resultTweenActive = false;
    this.resultTweenTimer = 0;
    this.resultTargetPercent = 0;
    this.lastChimePercent = 100;
    this.resultHpPercentText.text = "100%";
    this.resultHpLabelObj.setEnabledInHierarchy(false);
    this.resultHpPercentObj.setEnabledInHierarchy(false);
    this.setRetryVisible(false);
  }

  public showResult(winnerText: string, hpPercent: number): void {
    if (!this.ready) return;
    this.countdownLabel.text = winnerText;
    this.countdownLabel.fontSize = 30;
    this.countdownObj.setEnabledInHierarchy(true);
    this.resultHpLabelObj.setEnabledInHierarchy(true);
    this.resultHpPercentText.text = "100%";
    this.resultHpPercentObj.setEnabledInHierarchy(true);
    this.resultTargetPercent = Math.max(0, Math.min(100, hpPercent));
    this.resultTweenTimer = 0;
    this.lastChimePercent = 100;
    this.resultTweenActive = true;
    this.setRetryVisible(false);
  }

  onUpdate(dt: number): void {
    if (!this.ready || !this.resultTweenActive) return;
    this.resultTweenTimer = Math.min(3, this.resultTweenTimer + Math.max(0, dt));
    const progress = this.resultTweenTimer / 3;
    const eased = progress * progress * (3 - 2 * progress);
    const shownPercent = Math.round(100 + (this.resultTargetPercent - 100) * eased);
    const value = String(shownPercent) + "%";
    if (this.resultHpPercentText.text !== value) {
      this.resultHpPercentText.text = value;
      if (this.lastChimePercent - shownPercent >= UIManager.RESULT_CHIME_STEP) {
        this.resultChimeAudio.play();
        this.lastChimePercent = shownPercent;
      }
    }
    if (progress >= 1) {
      this.resultHpPercentText.text = String(this.resultTargetPercent) + "%";
      if (this.lastChimePercent !== this.resultTargetPercent) {
        this.resultChimeAudio.play();
        this.lastChimePercent = this.resultTargetPercent;
      }
      this.resultTweenActive = false;
      this.setRetryVisible(true);
      const event = APJS.EventManager.createEvent(this.resultCompleteType);
      APJS.EventManager.getGlobalEmitter().emit(event);
    }
  }
}

