  maxHp: number = 100;

  @serializeProperty
  @tooltip("Minimum normal damage dealt by one hit.")
  @spinBox(1, 50, 1)
  minDamage: number = 10;

  @serializeProperty
  @tooltip("Maximum normal damage dealt by one hit.")
  @spinBox(1, 50, 1)
  maxDamage: number = 15;

  @serializeProperty
  @tooltip("Chance for an attack to deal critical damage.")
  @slider(0, 0.5, 0.01)
  critRate: number = 0.15;

  @serializeProperty
  @tooltip("Critical damage multiplier.")
  @slider(1, 3, 0.1)
  critMultiplier: number = 2;

  @header("Turn Timing")
  @serializeProperty
  @tooltip("Preparation countdown duration before each exchange.")
  @spinBox(1, 30, 1)
  prepareSec: number = 10;

  @serializeProperty
  @tooltip("How long the WaterBall takes to fly to the other fighter.")
  @slider(0.1, 2, 0.1)
  flightSec: number = 0.5;

  @serializeProperty
  @tooltip("How long the impact splash remains visible.")
  @slider(0.2, 2, 0.1)
  impactSec: number = 1;

  @header("Mana Tuning")
  @serializeProperty
  @tooltip("Maximum mana for each fighter.")
  @spinBox(1, 20, 1)
  maxMana: number = 10;

  @serializeProperty
  @tooltip("Mana each fighter starts with.")
  @spinBox(0, 20, 1)
  startingMana: number = 5;

  @serializeProperty
  @tooltip("Mana restored to each fighter after a turn completes.")
  @spinBox(0, 10, 1)
  manaPerTurn: number = 1;

  onStart(): void {
    this.maxHp = this.clampInt(this.maxHp, 1, 500);
    this.minDamage = this.clampInt(this.minDamage, 1, 50);
    this.maxDamage = Math.max(this.minDamage, this.clampInt(this.maxDamage, 1, 50));
    this.critRate = this.clamp(this.critRate, 0, 0.5);
    this.critMultiplier = this.clamp(this.critMultiplier, 1, 3);
    this.prepareSec = this.clampInt(this.prepareSec, 1, 30);
    this.flightSec = this.clamp(this.flightSec, 0.1, 2);
    this.impactSec = this.clamp(this.impactSec, 0.2, 2);
    this.maxMana = this.clampInt(this.maxMana, 1, 20);
    this.startingMana = this.clampInt(this.startingMana, 0, this.maxMana);
    this.manaPerTurn = this.clampInt(this.manaPerTurn, 0, this.maxMana);
  }

  private clamp(value: number, min: number, max: number): number {
    return Math.max(min, Math.min(max, value));
  }

  private clampInt(value: number, min: number, max: number): number {
    return Math.round(this.clamp(value, min, max));
  }
}

@component()
export class DodgeButtonTest extends APJS.BasicScriptComponent {
  @serializeProperty
  buttonObj!: APJS.SceneObject;

  private buttonImage!: APJS.Image;
  private emitter!: APJS.EventEmitter;
  private onTouch = (event: APJS.IEvent): void => {
    const touch = event.args[0] as APJS.TouchData;
    if (touch.phase !== APJS.TouchPhase.Began || !this.buttonImage) return;
    if (APJS.TouchUtils.isScreenPointOnImage(touch.position, this.buttonImage)) {
      console.log("[Dodge] clicked");
    }
  };

  onStart(): void {
    if (!this.buttonObj) return;
    this.buttonImage = this.buttonObj.getComponent("Image") as APJS.Image;
    this.emitter = APJS.EventManager.getGlobalEmitter();
    this.emitter.on(APJS.EventType.Touch, this.onTouch);
  }

  onDestroy(): void {
    if (this.emitter) this.emitter.off(APJS.EventType.Touch, this.onTouch);
  }
}

